<?php require __DIR__.'/includes/bootstrap.php';requireRole('attendee');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}$bookingId=(int)($_POST['booking_id']??0);$statement=$pdo->prepare('SELECT event_id FROM bookings WHERE booking_id=? AND user_id=?');$statement->execute([$bookingId,currentUser()['user_id']]);$booking=$statement->fetch();if(!$booking){http_response_code(403);exit('Booking not found.');}$pdo->prepare('DELETE FROM bookings WHERE booking_id=? AND user_id=?')->execute([$bookingId,currentUser()['user_id']]);$statement=$pdo->prepare('SELECT u.name FROM waiting_list w JOIN users u ON u.user_id=w.user_id WHERE w.event_id=? ORDER BY w.joined_at,w.entry_id LIMIT 1');$statement->execute([$booking['event_id']]);$next=$statement->fetchColumn();flash($next?'Booking cancelled. Next in queue: '.$next.'.':'Booking cancelled.');redirect('my_bookings.php');
